#include "oblivion/restart_manager.hpp"
#include <Windows.h>
#include <RestartManager.h>
namespace oblivion {
std::vector<lock_owner> diagnose_lock_owners(const std::filesystem::path& path){ std::vector<lock_owner> owners; DWORD session=0; WCHAR key[CCH_RM_SESSION_KEY+1]{}; if(RmStartSession(&session,0,key)!=ERROR_SUCCESS) return owners; const std::wstring p=path.wstring(); LPCWSTR resources[]={p.c_str()}; if(RmRegisterResources(session,1,resources,0,nullptr,0,nullptr)!=ERROR_SUCCESS){RmEndSession(session);return owners;} UINT needed=0,count=0; DWORD reasons=0; DWORD st=RmGetList(session,&needed,&count,nullptr,&reasons); if(st==ERROR_MORE_DATA&&needed>0){ std::vector<RM_PROCESS_INFO> v(needed); count=needed; st=RmGetList(session,&needed,&count,v.data(),&reasons); if(st==ERROR_SUCCESS){ for(UINT i=0;i<count;++i) owners.push_back({v[i].Process.dwProcessId,v[i].strAppName,v[i].strServiceShortName}); }} RmEndSession(session); return owners; }
std::wstring format_lock_owners(const std::vector<lock_owner>& owners){ if(owners.empty()) return L"Kein verantwortlicher Prozess konnte über den Windows Restart Manager ermittelt werden."; std::wstring s=L"Die Datei wird verwendet von:\n"; for(const auto&o:owners){s+=L"\n- "+(o.application_name.empty()?std::wstring{L"Unbekannter Prozess"}:o.application_name)+L" (PID "+std::to_wstring(o.process_id)+L")"; if(!o.service_name.empty())s+=L" [Dienst: "+o.service_name+L"]";} return s; }
}
